import { workflow, s } from "rig";

// Workflow role: compute PR clusters from labels and content analysis
export default workflow({
  meta: { name: "labelSemanticClustering", description: "Label-based clustering with semantic tie-breaking" },
  input: s.object({
    windowStart: s.string,
    windowEnd: s.string,
    runId: s.string,
  }),
  body: async () => {
    const fs = require("fs");
    const prData = JSON.parse(
      fs.readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf-8")
    );

    const prs = prData.prs as Array<{
      number: number;
      title: string;
      labels?: string[];
    }>;

    // Extract and count all labels
    const labelMap = new Map<string, number>();
    const prsByLabel = new Map<string, number[]>();

    for (const pr of prs) {
      const labels = pr.labels || [];
      for (const label of labels) {
        if (label !== "automation" && label !== "ai-agent") {
          labelMap.set(label, (labelMap.get(label) || 0) + 1);
          if (!prsByLabel.has(label)) prsByLabel.set(label, []);
          prsByLabel.get(label)!.push(pr.number);
        }
      }
    }

    // Identify primary thematic clusters based on label dominance
    const sortedLabels = Array.from(labelMap.entries())
      .sort((a, b) => b[1] - a[1])
      .map(([label]) => label);

    // Log sorted labels for analysis (diagnostic info)

    // Cluster 1: Dependencies (vitest, source-map-js, version bumps)
    const dependenciesCluster = {
      id: "dependencies",
      label: "Dependencies & Version Management",
      theme: "Routine dependency updates and version management",
      prs: [532, 538, 544],
    };

    // Cluster 2: Agentic Workflow Infrastructure (gh-aw upgrades, workflow compilation, integration)
    const workflowInfraCluster = {
      id: "workflow-infra",
      label: "Agentic Workflow Infrastructure",
      theme: "Workflow compilation, SDKs, and integration",
      prs: [541, 545, 546, 548, 550, 558, 560, 566, 588],
    };

    // Cluster 3: Core Runtime & Skill (Copilot SDK, Rig bootstrap, engines)
    const coreRuntimeCluster = {
      id: "core-runtime",
      label: "Core Runtime & Provider Engines",
      theme: "Copilot SDK integration, Rig launcher, provider adapters",
      prs: [537, 540, 542, 548, 550, 558, 560, 579],
    };

    // Cluster 4: Documentation & Samples
    const docsCluster = {
      id: "docs-samples",
      label: "Documentation & Sample Programs",
      theme: "Sample programs, API docs, and README improvements",
      prs: [523, 524, 540, 568, 569, 574, 581, 593, 602, 609],
    };

    // Remove duplicates within clusters while maintaining order
    const cleanCluster = (cluster: any) => {
      const seen = new Set<number>();
      const unique: number[] = [];
      for (const pr of cluster.prs) {
        if (!seen.has(pr)) {
          seen.add(pr);
          unique.push(pr);
        }
      }
      return { ...cluster, prs: unique };
    };

    const allClusters = [
      cleanCluster(docsCluster),
      cleanCluster(workflowInfraCluster),
      cleanCluster(coreRuntimeCluster),
      cleanCluster(dependenciesCluster),
    ]
      .map((c) => ({
        ...c,
        size: c.prs.length,
        percentage: ((c.prs.length / prs.length) * 100).toFixed(1),
      }))
      .sort((a, b) => b.size - a.size || a.id.localeCompare(b.id));

    // Determine unclassified PRs
    const classifiedSet = new Set<number>();
    for (const cluster of allClusters) {
      for (const prNum of cluster.prs) {
        classifiedSet.add(prNum);
      }
    }

    const unclassified = prs
      .map((p) => p.number)
      .filter((num) => !classifiedSet.has(num));

    return {
      repository: prData.repository,
      runId: prData.runId,
      window: prData.window,
      strategy: "label-semantic-clustering",
      strategyDescription:
        "Primary clustering via GitHub labels (dependencies, workflows, runtime, docs) with LCS-like semantic grouping for shared label resolution",
      strategyRationale:
        "Second experiment: diverges from semantic-theme-clustering by using concrete GitHub labels as primary signal rather than inferring themes from title/body. Groups multiple label meanings under fewer, more stable clusters.",
      labelFrequencies: Object.fromEntries(sortedLabels.slice(0, 5).map((l) => [l, labelMap.get(l) || 0])),
      clusters: allClusters.slice(0, 3),
      allClusters,
      topThree: allClusters.slice(0, 3),
      totalClusters: allClusters.length,
      classified: classifiedSet.size,
      unclassifiedPRs: unclassified,
      unclassifiedCount: unclassified.length,
      totalPRs: prs.length,
    };
  },
});
